# ── Flowi rc1: допоміжне (поза бібліотекою) ────────────────────────────────
# Усі секрети — лише в ~/.flowi-signing (0700, файли 0600), ніколи в репозиторіях.
SIGN_DIR="${FLOWI_SIGNING_DIR:-$HOME/.flowi-signing}"
ENV_FILE="$SIGN_DIR/owner.env"
MOBILE_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
VPS_IP="159.89.99.91"
APP_HOST="app.flowi.com.ua"
API_HOST="api.flowi.com.ua"
APP_ID="app.flowi.mobile"
KEYSTORE="$SIGN_DIR/flowi-upload.jks"
KEY_ALIAS="flowi-upload"
GRADLE_PROPS="$HOME/.gradle/gradle.properties"

# gradle_prop KEY VALUE — upsert у ~/.gradle/gradle.properties БЕЗ лапок
# (Gradle прочитав би лапки як частину значення).
gradle_prop() {
  local key="$1" value="$2" tmp
  mkdir -p "$(dirname "$GRADLE_PROPS")"
  [[ -e "$GRADLE_PROPS" ]] || (umask 077 && : > "$GRADLE_PROPS")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$GRADLE_PROPS" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  cat "$tmp" > "$GRADLE_PROPS"
  rm -f "$tmp"
  chmod 600 "$GRADLE_PROPS"
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$GRADLE_PROPS"
}

# copy_secret_file SRC DEST — копія з правами 0600; не перезаписує мовчки.
copy_secret_file() {
  local src="$1" dest="$2"
  [[ -f "$src" ]] || { warn "файл не знайдено: $src"; return 1; }
  if [[ -e "$dest" ]] && ! cmp -s "$src" "$dest"; then
    confirm "$dest уже існує й відрізняється. Замінити?" || { note "лишаю наявний $dest"; return 0; }
  fi
  (umask 077 && cp "$src" "$dest")
  chmod 600 "$dest"
  printf '  %s✓ saved%s %s\n' "$GREEN" "$RESET" "$dest"
}

# check_url URL — статус, Content-Type і редирект БЕЗ -L (Apple/Google за редиректами не йдуть).
check_url() {
  local url="$1" out code ctype redirect
  out=$(curl -sS -o /dev/null --max-time 15 -w '%{http_code}|%{content_type}|%{redirect_url}' "$url" 2>&1) || true
  code="${out%%|*}"; out="${out#*|}"; ctype="${out%%|*}"; redirect="${out#*|}"
  printf '  %s\n    status=%s  content-type=%s  redirect=%s\n' "$url" "$code" "${ctype:-—}" "${redirect:-немає}"
  if [[ "$code" == "200" && "$ctype" == application/json* && -z "$redirect" ]]; then
    printf '    %s✓ OK%s\n' "$GREEN" "$RESET"
    if curl -sS --max-time 15 "$url" | python3 -c 'import json,sys; json.load(sys.stdin)' 2>/dev/null; then
      note "  JSON валідний"
    else
      warn "  тіло не є валідним JSON"; SKIPPED+=("$url: невалідний JSON")
    fi
  else
    warn "  очікувалось 200 + application/json + без редиректу"
    SKIPPED+=("перевірка $url (status=$code, type=$ctype, redirect=$redirect)")
  fi
}

run_wizard() {

TOTAL_STAGES=16

banner "Flowi rc1 — налаштування власника (Apple, Google, Firebase, DNS, пошта)"

# ── 1 ──────────────────────────────────────────────────────────────────────
stage "Сховище секретів ~/.flowi-signing"
say "Усе, що знає лише власник (ключі, паролі, JSON), лежатиме тут, поза git:"
