say "Значення, які майстер запамʼятовує між запусками: $ENV_FILE"
mkdir -p "$SIGN_DIR"; chmod 700 "$SIGN_DIR"
[[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
chmod 600 "$ENV_FILE"
printf '  %s✓ ready%s %s\n' "$GREEN" "$RESET" "$SIGN_DIR"
warn "Резервна копія: цю теку треба зберегти поза ноутбуком (менеджер паролів / зашифрований диск)."
pause

# ── 2 ──────────────────────────────────────────────────────────────────────
stage "Apple: Team ID нового акаунта"
open_url "https://developer.apple.com/account"
step "Увійдіть НОВИМ Apple Developer акаунтом → розділ Membership details."
step "Скопіюйте Team ID (10 символів, A–Z і цифри)."
while :; do
  ask FLOWI_APPLE_TEAM_ID "Team ID:"
  [[ "$FLOWI_APPLE_TEAM_ID" =~ ^[A-Z0-9]{10}$ ]] && break
  warn "Team ID — рівно 10 символів A–Z/0–9."
done
write_env FLOWI_APPLE_TEAM_ID "$FLOWI_APPLE_TEAM_ID"
note "Для збірки: export FLOWI_APPLE_TEAM_ID=$FLOWI_APPLE_TEAM_ID перед 'npx expo prebuild' (app.config.js)."
PBX="$MOBILE_ROOT/ios/Flowi.xcodeproj/project.pbxproj"
if [[ -f "$PBX" ]] && confirm "Прописати цей Team ID у локальний ios/Flowi.xcodeproj (застосунок, віджет, годинник)?"; then
  sed -i.bak -E "s/(DEVELOPMENT_TEAM = )[A-Z0-9]+;/\1${FLOWI_APPLE_TEAM_ID};/; s/(DevelopmentTeam = )[A-Z0-9]+;/\1${FLOWI_APPLE_TEAM_ID};/" "$PBX"
  rm -f "$PBX.bak"
  printf '  %s✓ patched%s %s\n' "$GREEN" "$RESET" "$PBX"
fi
pause

# ── 3 ──────────────────────────────────────────────────────────────────────
stage "Apple: App Group"
open_url "https://developer.apple.com/account/resources/identifiers/list/applicationGroup"
step "Identifiers → «+» → App Groups → Continue."
step "Description: Flowi;  Identifier: group.$APP_ID → Register."
note "Віджет і застосунок обмінюються знімком і чергою дій саме через цю групу."
