# ── 4 ──────────────────────────────────────────────────────────────────────
stage "Apple: App IDs і capabilities"
open_url "https://developer.apple.com/account/resources/identifiers/list"
say "Створіть три App ID (Identifiers → «+» → App IDs → App), Bundle ID — Explicit:"
step "$APP_ID  (Flowi): App Groups [group.$APP_ID], Associated Domains, HealthKit (+ Background Delivery), Push Notifications."
step "$APP_ID.widget  (Flowi Widget): App Groups [group.$APP_ID], HealthKit."
step "$APP_ID.watchkitapp  (Flowi Watch): без додаткових capabilities."
note "Після реєстрації для $APP_ID і .widget: Edit → App Groups → Configure → обрати group.$APP_ID → Save."
note "Профілі підпису Xcode створить сам (Automatically manage signing) після вибору команди."
pause "Три App ID створено й налаштовано? Enter"

# ── 5 ──────────────────────────────────────────────────────────────────────
stage "Apple: ключ APNs (.p8)"
open_url "https://developer.apple.com/account/resources/authkeys/list"
step "Keys → «+» → назва «Flowi APNs» → увімкнути Apple Push Notifications service (APNs) → Continue → Register."
step "Скопіюйте Key ID і натисніть Download (файл AuthKey_<KEYID>.p8 завантажується ЛИШЕ раз)."
while :; do
  ask APNS_KEY_ID "Key ID:"
  [[ "$APNS_KEY_ID" =~ ^[A-Z0-9]{10}$ ]] && break
  warn "Key ID — 10 символів A–Z/0–9."
done
write_env APNS_KEY_ID "$APNS_KEY_ID"
ask APNS_P8_DOWNLOAD "Шлях до завантаженого .p8 (напр. ~/Downloads/AuthKey_$APNS_KEY_ID.p8):"
APNS_P8_DOWNLOAD="${APNS_P8_DOWNLOAD/#\~/$HOME}"
APNS_P8_LOCAL="$SIGN_DIR/AuthKey_$APNS_KEY_ID.p8"
