# ── 6 ──────────────────────────────────────────────────────────────────────
stage "App Store Connect: запис застосунку і посилання на App Store"
open_url "https://appstoreconnect.apple.com/apps"
step "Apps → «+» → New App → iOS; Name: Flowi; Primary language: Ukrainian; Bundle ID: $APP_ID; SKU: flowi-mobile."
