ask FLOWI_IOS_APPLE_ID "Apple ID застосунку (лише цифри):"
FLOWI_IOS_STORE_URL="https://apps.apple.com/app/id${FLOWI_IOS_APPLE_ID}"
write_env FLOWI_IOS_STORE_URL "$FLOWI_IOS_STORE_URL"
