# ── 7 ──────────────────────────────────────────────────────────────────────
stage "Android: upload keystore"
say "Upload-ключ підписує AAB, які ви вантажите в Play. Сам застосунок для користувачів"
say "підписує Google (Play App Signing). Втрата upload-ключа = звернення в підтримку Google."
if [[ -e "$KEYSTORE" ]]; then
  note "Keystore уже існує: $KEYSTORE — НЕ перезаписую."
  while :; do
    ask_secret FLOWI_UPLOAD_STORE_PASSWORD "Пароль наявного keystore:"
    if FLOWI_KS_PASS="$FLOWI_UPLOAD_STORE_PASSWORD" keytool -list -keystore "$KEYSTORE" \
        -alias "$KEY_ALIAS" -storepass:env FLOWI_KS_PASS >/dev/null 2>&1; then break; fi
    warn "Пароль не підходить (або alias $KEY_ALIAS відсутній) — спробуйте ще раз."
  done
else
  command -v keytool >/dev/null 2>&1 || { warn "keytool не знайдено (потрібен JDK 17, напр. brew install openjdk@17)"; pause "Встановіть і натисніть Enter"; }
  while :; do
    ask_secret FLOWI_UPLOAD_STORE_PASSWORD "Новий пароль keystore (≥ 12 символів):"
    [[ ${#FLOWI_UPLOAD_STORE_PASSWORD} -ge 12 ]] && break
    warn "Закоротко."
  done
  ask FLOWI_KEY_DNAME "Власник сертифіката (напр. CN=Flowi, O=Flowi, C=UA):"
  if confirm "Згенерувати $KEYSTORE (RSA 4096, 10000 днів)?"; then
    FLOWI_KS_PASS="$FLOWI_UPLOAD_STORE_PASSWORD" keytool -genkeypair -v -storetype PKCS12 \
      -keystore "$KEYSTORE" -alias "$KEY_ALIAS" -keyalg RSA -keysize 4096 -validity 10000 \
      -dname "$FLOWI_KEY_DNAME" -storepass:env FLOWI_KS_PASS -keypass:env FLOWI_KS_PASS
    chmod 600 "$KEYSTORE"
  else
    SKIPPED+=("upload keystore $KEYSTORE")
  fi
fi
write_env FLOWI_UPLOAD_STORE_PASSWORD "$FLOWI_UPLOAD_STORE_PASSWORD"
if [[ -f "$KEYSTORE" ]]; then
  FLOWI_UPLOAD_SHA256=$( (FLOWI_KS_PASS="$FLOWI_UPLOAD_STORE_PASSWORD" keytool -list -v -keystore "$KEYSTORE" \
    -alias "$KEY_ALIAS" -storepass:env FLOWI_KS_PASS 2>/dev/null || true) | awk '/SHA256:/ {print $2; exit}')
  if [[ -n "$FLOWI_UPLOAD_SHA256" ]]; then
    write_env FLOWI_UPLOAD_SHA256 "$FLOWI_UPLOAD_SHA256"
    note "Upload key SHA-256: $FLOWI_UPLOAD_SHA256"
  else
    warn "Не вдалося прочитати SHA-256 upload-ключа"; SKIPPED+=("SHA-256 upload-ключа")
  fi
fi
