# ── 11 ─────────────────────────────────────────────────────────────────────
stage "DNS flowi.com.ua"
say "У панелі DNS реєстратора flowi.com.ua створіть записи:"
step "A     api   → $VPS_IP   (TTL 300 на час переїзду)"
step "A     app   → $VPS_IP"
note "Поштові записи (SPF/DKIM/DMARC) — лише коли налаштовуєте пошту (етап 12); існуючий SPF реєстратора не чіпайте."
note "Деталі й значення-заготовки: docs/release-rc1/identity-signing-domains.md (розділ DNS)."
pause "Записи створено? Enter — перевіримо"
for h in "$API_HOST" "$APP_HOST"; do
  got=$(dig +short A "$h" 2>/dev/null | tail -n1 || true)
  if [[ "$got" == "$VPS_IP" ]]; then printf '  %s✓%s %s → %s\n' "$GREEN" "$RESET" "$h" "$got"
  else warn "$h → '${got:-нічого}' (очікувалось $VPS_IP; DNS може ще поширюватись)"; SKIPPED+=("DNS A $h"); fi
done
note "SPF: $(dig +short TXT flowi.com.ua 2>/dev/null | grep -i spf1 || echo 'ще не видно')"
note "DMARC: $(dig +short TXT _dmarc.flowi.com.ua 2>/dev/null || echo 'ще не видно')"
pause

# ── 12 ─────────────────────────────────────────────────────────────────────
stage "Пошта: smarthost для Postfix (необовʼязково)"
say "Django шле на локальний Postfix (localhost:25), Postfix — на smarthost:587."
note "Шаблони: flowi-server-app/ops/postfix/{main.cf.template,sasl_passwd.template,flowi-email.env.template,dns-records.txt}"
note "Runbook: docs/release-rc1/email.md"
note "Можна пропустити: без EMAIL_HOST пошта на сервері вимкнена, інвайти працюють посиланням (delivery_status=skipped)."
MAIL_ENABLED=0
if confirm "Налаштувати пошту зараз?"; then
MAIL_ENABLED=1
ask SMTP_RELAY_HOST "Smarthost (host, напр. smtp.example.com):"
ask SMTP_RELAY_PORT "Порт smarthost [587]:"
SMTP_RELAY_PORT="${SMTP_RELAY_PORT:-587}"
ask SMTP_RELAY_USER "Логін smarthost:"
ask_secret SMTP_RELAY_PASSWORD "Пароль smarthost:"
write_env SMTP_RELAY_HOST "$SMTP_RELAY_HOST"
write_env SMTP_RELAY_PORT "$SMTP_RELAY_PORT"
write_env SMTP_RELAY_USER "$SMTP_RELAY_USER"
write_env SMTP_RELAY_PASSWORD "$SMTP_RELAY_PASSWORD"
else
SKIPPED+=("Пошта (Postfix relay, SPF/DKIM/DMARC) — пропущено; запустіть wizard ще раз, коли будете готові")
fi
pause

# ── 13 ─────────────────────────────────────────────────────────────────────
stage "Перша release-збірка Android і Play Console"
say "Play App Signing SHA-256 зʼявляється після першого завантаження AAB."
step "У терміналі: cd \"$MOBILE_ROOT\" && npm run build-number && npx expo prebuild --platform android && (cd android && ./gradlew bundleRelease)"
note "AAB: android/app/build/outputs/bundle/release/app-release.aab"
open_url "https://play.google.com/console"
step "Create app → Flowi, мова Українська, App, Free → Create."
step "Test and release → Testing → Internal testing → Create new release → завантажте AAB (погодьтеся на Play App Signing)."
step "Test and release → Setup → App integrity → App signing → «App signing key certificate» → SHA-256 — скопіюйте."
ask FLOWI_PLAY_SIGNING_SHA256 "SHA-256 ключа Play App Signing (AA:BB:…):"
write_env FLOWI_PLAY_SIGNING_SHA256 "$FLOWI_PLAY_SIGNING_SHA256"
FLOWI_ANDROID_SHA256_CERTS="$FLOWI_PLAY_SIGNING_SHA256"
[[ -n "${FLOWI_UPLOAD_SHA256:-}" ]] && FLOWI_ANDROID_SHA256_CERTS="$FLOWI_ANDROID_SHA256_CERTS,$FLOWI_UPLOAD_SHA256"
write_env FLOWI_ANDROID_SHA256_CERTS "$FLOWI_ANDROID_SHA256_CERTS"
note "Порівняйте з «Upload key certificate» на тій самій сторінці: це має бути ${FLOWI_UPLOAD_SHA256:-(невідомо)}"
pause

# ── 14 ─────────────────────────────────────────────────────────────────────
stage "Значення для VPS (готові фрагменти env)"
VPS_DIR="$SIGN_DIR/vps"; mkdir -p "$VPS_DIR"; chmod 700 "$VPS_DIR"
(umask 077 && cat > "$VPS_DIR/api.env.snippet" <<EOF
# → /var/www/flowi-api/.env на VPS (дописати/замінити ці рядки), потім systemctl restart flowi-api flowi-worker
ALLOWED_HOSTS=$API_HOST,$APP_HOST,api.flowi.casperdev.site,localhost,127.0.0.1
WEB_APP_URL=https://$APP_HOST
PUBLIC_API_URL=https://$API_HOST
PUBLIC_WS_URL=wss://$API_HOST/ws
CORS_EXTRA_ORIGINS=https://$APP_HOST
DEFAULT_FROM_EMAIL='Flowi <noreply@flowi.com.ua>'
SERVER_EMAIL='Flowi <noreply@flowi.com.ua>'
$(if [[ "${MAIL_ENABLED:-0}" == 1 ]]; then printf '%s\n' 'EMAIL_HOST=localhost' 'EMAIL_PORT=25' 'EMAIL_USE_TLS=False' 'EMAIL_NO_AUTH=True' '# Прибрати старі EMAIL_USER / EMAIL_PASSWORD, якщо були.'; else printf '%s\n' '# Пошта пропущена: НЕ задавати EMAIL_HOST (і прибрати старі EMAIL_HOST/EMAIL_USER/EMAIL_PASSWORD) — канал вимкнено.'; fi)
APNS_KEY_FILE=/etc/flowi/secrets/AuthKey_${APNS_KEY_ID:-KEYID}.p8
APNS_KEY_ID=${APNS_KEY_ID:-}
APNS_TEAM_ID=${FLOWI_APPLE_TEAM_ID:-}
APNS_TOPIC=$APP_ID
APNS_USE_SANDBOX=False
FCM_SERVICE_ACCOUNT_FILE=/etc/flowi/secrets/fcm-service-account.json
FCM_PROJECT_ID=${FCM_PROJECT_ID:-}
FLOWI_IOS_STORE_URL=${FLOWI_IOS_STORE_URL:-}
FLOWI_ANDROID_STORE_URL=https://play.google.com/store/apps/details?id=$APP_ID
# Після релізу 1.4.0 і появи в сторах (НЕ раніше): MIN_MOBILE_VERSION=1.4.0
EOF
cat > "$VPS_DIR/web.env.snippet" <<EOF
# → /etc/flowi/web.env на VPS, потім systemctl restart flowi-web
FLOWI_APPLE_TEAM_ID=${FLOWI_APPLE_TEAM_ID:-}
FLOWI_IOS_BUNDLE_ID=$APP_ID
FLOWI_ANDROID_PACKAGE=$APP_ID
FLOWI_ANDROID_SHA256_CERTS=${FLOWI_ANDROID_SHA256_CERTS:-}
EOF
if [[ "${MAIL_ENABLED:-0}" == 1 ]]; then
cat > "$VPS_DIR/postfix-sasl_passwd" <<EOF
# → /etc/postfix/sasl_passwd (формат ops/postfix/sasl_passwd.template); main.cf: relayhost = [${SMTP_RELAY_HOST:-smtp.example.com}]:${SMTP_RELAY_PORT:-587}
[${SMTP_RELAY_HOST:-smtp.example.com}]:${SMTP_RELAY_PORT:-587} ${SMTP_RELAY_USER:-user}:${SMTP_RELAY_PASSWORD:-password}
EOF
fi
)
printf '  %s✓ wrote%s %s/{api.env.snippet,web.env.snippet%s}\n' "$GREEN" "$RESET" "$VPS_DIR" "$([[ "${MAIL_ENABLED:-0}" == 1 ]] && echo ',postfix-sasl_passwd')"
say "Скопіюйте на VPS (root):"
step "ssh root@$VPS_IP 'install -d -m 700 /etc/flowi/secrets'"
step "scp \"${APNS_P8_LOCAL:-$SIGN_DIR/AuthKey_KEYID.p8}\" \"$SIGN_DIR/fcm-service-account.json\" root@$VPS_IP:/etc/flowi/secrets/ && ssh root@$VPS_IP 'chmod 600 /etc/flowi/secrets/*'"
step "Рядки з $VPS_DIR/api.env.snippet → /var/www/flowi-api/.env; з web.env.snippet → /etc/flowi/web.env."
if [[ "${MAIL_ENABLED:-0}" == 1 ]]; then step "postfix-sasl_passwd → /etc/postfix/sasl_passwd; chmod 600; postmap /etc/postfix/sasl_passwd; main.cf з ops/postfix/main.cf.template; systemctl reload postfix."; fi
step "Звірте upstream-и: systemctl cat flowi-api (порт Daphne) і nginx -T | grep proxy_pass; за потреби FLOWI_API_UPSTREAM/FLOWI_WEB_UPSTREAM у env Caddy."
step "Caddy: flowi-server-app/ops/caddy/Caddyfile.production → /etc/caddy/Caddyfile; caddy validate --config /etc/caddy/Caddyfile."
step "Перемикання 80/443: systemctl disable --now nginx && systemctl enable --now caddy (GlitchTip :8443 — див. runbook §7)."
step "systemctl restart flowi-api flowi-worker flowi-web"
warn "НЕ ставте MIN_MOBILE_VERSION=1.4.0, доки 1.4.0 не доступна в обох сторах."
pause "Зроблено на VPS? Enter — перевіримо"

# ── 15 ─────────────────────────────────────────────────────────────────────
stage "Перевірка: .well-known і хости"
check_url "https://$APP_HOST/.well-known/apple-app-site-association"
check_url "https://$APP_HOST/.well-known/assetlinks.json"
say "Хости:"
for u in "https://$API_HOST/api/health/" "https://$APP_HOST/healthz" "https://api.flowi.casperdev.site/api/health/"; do
  printf '  %s → %s\n' "$u" "$(curl -sS -o /dev/null --max-time 15 -w '%{http_code}' "$u" 2>/dev/null || echo ERR)"
done
printf '  old web redirect: %s\n' "$(curl -sS -o /dev/null --max-time 15 -w '%{http_code} → %{redirect_url}' "https://api.flowi.casperdev.site/invite?x=1" 2>/dev/null || echo ERR)"
note "Очікується: 200, 200, 200 і «301 → https://$APP_HOST/invite?x=1»."
pause

# ── 16 ─────────────────────────────────────────────────────────────────────
stage "Перевірка: Google Digital Asset Links і Apple CDN"
DAL="https://digitalassetlinks.googleapis.com/v1/assetlinks:check?source.web.site=https://$APP_HOST&relation=delegate_permission/common.handle_all_urls&target.android_app.package_name=$APP_ID"
FIRST_SHA="${FLOWI_ANDROID_SHA256_CERTS%%,*}"
if [[ -n "$FIRST_SHA" ]]; then
  DAL="$DAL&target.android_app.certificate.sha256_fingerprint=$FIRST_SHA"
  res=$(curl -sS --max-time 20 "$DAL" 2>&1 || true)
  printf '  %s\n' "$res" | head -n 8
  if printf '%s' "$res" | grep -q '"linked": *true'; then printf '  %s✓ Google: linked=true%s\n' "$GREEN" "$RESET"
  else warn "Google ще не бачить звʼязку (кеш до ~доби, або помилка у відбитках)"; SKIPPED+=("Google DAL check"); fi
else
  warn "FLOWI_ANDROID_SHA256_CERTS порожнє — пропускаю"; SKIPPED+=("Google DAL check")
fi
say "Apple CDN (оновлюється до ~доби після першого запиту):"
printf '  %s\n' "$(curl -sS -o /dev/null --max-time 20 -w '%{http_code} %{content_type}' "https://app-site-association.cdn-apple.com/a/v1/$APP_HOST" 2>/dev/null || echo ERR)"
note "На пристрої: Android — adb shell pm verify-app-links --re-verify $APP_ID; adb shell pm get-app-links $APP_ID"
note "iOS — Settings → Developer → Universal Links → Diagnostics → https://$APP_HOST/app/today"
pause

finish
say "Значення збережено в $ENV_FILE (0600). Збірки:"
say "  export FLOWI_APPLE_TEAM_ID=\$(grep ^FLOWI_APPLE_TEAM_ID= \"$ENV_FILE\" | cut -d\"'\" -f2)"
say "Runbook: docs/release-rc1/identity-signing-domains.md"
}

run_wizard "$@"; exit
